// The pane, one screen at a time: no repository, still reading, nothing to
// walk (the welcome screen), or the walk itself.

import { commitSection, worktreePicker } from './commits'
import { debugButton, debugSection } from './debug'
import { fileSection } from './files'
import type { Frame } from './frame'
import { header } from './header'
import { rangeRow } from './ranges'
import { contentView, viewButtons } from './view'
import { chooseArt, welcomeArt } from './welcome'

export function drawPane(f: Frame) {
  const { Box, Text, Button } = f.ui
  const { snap } = f

  if (snap.repoRoot === null) {
    const art = chooseArt(f)
    if (snap.error) {
      return (
        <Box flexDirection="column" gap={1}>
          {welcomeArt(f, art.source)}
          <Text bold>No repository to review</Text>
          <Text color="red">{snap.error}</Text>
          <Text dimColor>Start Claude Code inside a Git repository, then run /commit-walk.</Text>
          <Box flexDirection="row" gap={1}>
            <Button key="refresh" hotkey="r" onPress={() => void f.act.load('repo')}>Try again</Button>
            {debugButton(f)}
          </Box>
          {debugSection(f, art.tier)}
        </Box>
      )
    }
    return (
      <Box flexDirection="column" gap={1}>
        {welcomeArt(f, art.source)}
        <Text dimColor>Reading the repository…</Text>
        {debugSection(f, art.tier)}
      </Box>
    )
  }

  if (snap.commits.length === 0) return nothingToWalk(f, snap.repoRoot)

  // The debug section sits under the header here: below the diff it would be off screen.
  return (
    <Box flexDirection="column" gap={1}>
      {header(f, snap.repoRoot)}
      {debugSection(f, null)}
      {worktreePicker(f)}
      {commitSection(f)}
      {fileSection(f)}
      {viewButtons(f)}
      {contentView(f)}
      <Text dimColor wrap="truncate-end">keys: o/n commit · k/j file · d/a/b view · h range · r refresh · x debug · Esc close</Text>
    </Box>
  )
}

/**
 * Nothing to walk: the welcome art, until a commit lands. Under "not in
 * default" that is the default branch itself (no work happens there) or a
 * branch level with it; otherwise a worktree with no commits at all.
 */
function nothingToWalk(f: Frame, repoRoot: string) {
  const { Box, Text, Button } = f.ui
  const { snap, sel } = f
  const worktree = snap.worktrees.find(wt => wt.path === sel.worktree)
  const where = worktree?.branch ?? 'this worktree'
  const defaultRef = snap.ranges.notInDefault?.ref ?? 'the default branch'
  const isNotInDefault = snap.range === 'notInDefault'
  const art = chooseArt(f)
  const showAll = (
    <Box>
      <Button key="show-all" onPress={() => void f.act.load('commit', { range: 'all', commit: null, file: null })}>
        Show all commits
      </Button>
    </Box>
  )
  return (
    <Box flexDirection="column" gap={1}>
      {header(f, repoRoot)}
      {debugSection(f, art.tier)}
      {worktreePicker(f)}
      {rangeRow(f)}
      {welcomeArt(f, art.source)}
      {isNotInDefault && snap.ranges.isOnDefault ? (
        <Box flexDirection="column" gap={1}>
          <Text>You're on {where}. Work happens on branches, so there is nothing new to walk here.</Text>
          <Text dimColor>Pick a worktree above, or show the whole history.</Text>
          {showAll}
        </Box>
      ) : isNotInDefault ? (
        <Box flexDirection="column" gap={1}>
          <Text>No commits on {where} beyond {defaultRef} yet.</Text>
          <Text dimColor>The pane follows the first one as soon as it lands. Press r to look again.</Text>
          {showAll}
        </Box>
      ) : (
        <Box flexDirection="column">
          <Text>No commits on {where} yet.</Text>
          <Text dimColor>The pane follows the first one as soon as it lands. Press r to look again.</Text>
        </Box>
      )}
    </Box>
  )
}

files.hooks/pane/frame.ts:
// What every part of the pane draws with: the values read for this draw, the
// actions its buttons take, the surface's elements, and the room it has.
//
// The pane's parts never take `$`: Claude Code before 2.1.300 follows `$`
// only into functions of the file that holds it. register.tsx reads the
// values and builds the actions; the parts here only draw.

import type { ElementTable } from 'claude-code'

import type { About, Expandable, GitTrace, Selection, Snapshot } from '../../types'
import type { Depth } from '../state'
import type { ListScroll } from '../window'

/** Everything the pane draws from, read once per draw. The debug values only while it is shown. */
export type PaneValues = {
  sel: Selection
  snap: Snapshot
  open: Expandable | null
  scrolled: Record<string, ListScroll>
  isDebug: boolean
  gitRuns: GitTrace[]
  where: About | null
}

/** What the pane's buttons do; each starts its work and returns at once. */
export type Actions = {
  load: (depth: Depth, change?: Partial<Selection>) => void
  stepCommit: (delta: 1 | -1) => void
  stepFile: (delta: 1 | -1) => void
  toggleDebug: () => void
  toggleList: (which: Expandable) => void
  foldLists: () => void
  scrollList: (prefix: string, at: ListScroll) => void
}

/** Where the pane is drawn, from the render event. */
export type Place = { bodyColumns: number; bodyRows: number; placement: string; surface: string }

export type Frame = PaneValues & {
  act: Actions
  /** The surface's elements: Box, Text, Button, Code. */
  ui: ElementTable
  place: Place
  /** Columns to draw in, never fewer than 24. */
  width: number
  /** A framed list's inner width: lists are whole-row buttons, so a row is that wide. */
  inner: number
}

export function frameOf(values: PaneValues, act: Actions, ui: ElementTable, place: Place): Frame {
  const width = Math.max(24, place.bodyColumns)
  return { ...values, act, ui, place, width, inner: Math.max(10, width - 2) }
}

/** `text` padded or cut to exactly `room` columns, a framed row by default. */
export function pad(f: Frame, text: string, room = f.inner): string {
  return text.padEnd(room).slice(0, room)
}

